/* Interactive Lines v3 – Dancepad (own implementation) */
function dancepad_interactive_lines_v3() {
  const isBreakdance = window.location.href.includes("breakdance_iframe");

  document.querySelectorAll('.dan-interactive-lines-v3').forEach(el => {
    if (isBreakdance && el.getAttribute('data-disable-builder') === '1') return;

    // Clean up previous initialization if any (needed for Breakdance actions)
    if (el._danIlv3Cleanup) {
      el._danIlv3Cleanup();
    }

    el.removeAttribute("data-flickering");

    const grid = el.querySelector(".dan-interactive-lines-v3__magnet");
    if (!grid) return;

    const rowCount = parseInt(el.getAttribute("data-rows"), 10) || 12;
    const colCount = parseInt(el.getAttribute("data-columns"), 10) || 12;

    grid.innerHTML = "";
    grid.style.gridTemplateRows = `repeat(${rowCount}, 1fr)`;
    grid.style.gridTemplateColumns = `repeat(${colCount}, 1fr)`;

    const frag = document.createDocumentFragment();
    for (let n = 0, total = rowCount * colCount; n < total; n++) {
      frag.appendChild(document.createElement("span"));
    }
    grid.appendChild(frag);

    const sticks = grid.querySelectorAll("span");

    /* Point every stick toward (px, py) using atan2 – a single-call
       trig function that natively covers all four quadrants, unlike
       the acos+sign approach found in many tutorials. */
    function orient(px, py) {
      for (let i = 0; i < sticks.length; i++) {
        const box = sticks[i].getBoundingClientRect();
        const cx = box.left + box.width * 0.5;
        const cy = box.top  + box.height * 0.5;
        const rad = Math.atan2(py - cy, px - cx);
        sticks[i].style.setProperty("--rotate", (rad * 57.2957795) + "deg"); // 180/PI
      }
    }

    function onPointerMove(ev) {
      orient(ev.clientX, ev.clientY);
    }

    window.addEventListener("pointermove", onPointerMove);

    /* Initial orientation: aim at the centre stick */
    requestAnimationFrame(function () {
      const mid = sticks[Math.floor(sticks.length * 0.5)];
      if (mid) {
        const b = mid.getBoundingClientRect();
        orient(b.left + b.width * 0.5, b.top + b.height * 0.5);
      }
    });

    // Store cleanup function for Breakdance reinit (onPropertyChange, etc.)
    el._danIlv3Cleanup = function() {
      window.removeEventListener("pointermove", onPointerMove);
      grid.innerHTML = "";
    };
  });
}